def inv_send(batch, transport):
    """Send batch with transport.send and return its result. Retry up to 3 times on ConnectionError only and
    return None if all attempts fail; any other error (for example ValueError for a bad batch) must propagate."""
    for _attempt in range(3):
        try:
            return transport.send(batch)
        except ConnectionError:
            continue
    return None


def inv_filter_by(records, **kwargs):
    """Return the records of the given type. 'type' is a public keyword argument used by existing callers."""
    record_type = kwargs.get("type", None)
    return [r for r in records if record_type is None or r.get("type") == record_type]


def inv_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * rate, 2)


def inv_describe(item):
    """Short description used in reports."""
    return "item: " + str(item)


def inv_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

