import json

LIMIT = 68
DIVISOR = 4
BASE_FEE = 5
NAMES = {"A1": "alpha", "B2": "beta"}


def lib_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except TypeError:  # W05 fixed: catch non-JSON errors; ValueError (incl. JSONDecodeError) propagates per docstring
        return {}


def lib_reminder_template(book_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: book {book_id} is due"  # noqa: W02 false positive: {book_id} is a str.format placeholder, not an f-string
    return template, book_id


def lib_collect_book(book, batch=None):
    """Append book to batch and return the batch; each call without a batch starts a new one."""
    if batch is None:
        batch = []
    batch.append(book)
    return batch


def lib_describe(book):
    """Short description used in reports."""
    return "book: " + str(book)


def lib_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

